import {symbol} from './ui-visuals.js';
import {hospitals,resources,distance} from './seed.js';
import {sampleStaff} from './sample-staff.js';
const sampleAssignment=s=>sampleStaff.find(x=>x.email===s.email);
const fixedSample=s=>!!sampleAssignment(s);
const assignedRole=s=>sampleAssignment(s)?.role||s.role||s.requestedRole;
const assignedFacility=s=>sampleAssignment(s)?.facilityId||s.facilityId||s.requestedFacility;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let actor;const expanded=new Set();
function resourceHelpCards(requests,facilities){const rows=requests.filter(r=>r.status==='Needs admin');return `<section id="resource-help" class="panel resource-help-queue"><div class="core-panel-head"><h2>Resource help</h2><span class="tag" data-testid="resource-help-count">${rows.length}</span></div><p>EMS needs help finding a hospital. Contact a hospital to check support, then send the request to its team.</p><div data-testid="resource-help-list">${rows.map(r=>{const origin=hospitals.find(h=>h.id===r.hospitalId),candidates=facilities.filter(h=>h.state!=='Closed'&&h.acceptingRequests!==false&&distance(origin,h)<=r.radiusKm&&(!resources.includes(r.resource)||h.resources.includes(r.resource)));return `<article class="staff-card" data-testid="resource-help-${r.id}"><strong>${esc(r.resource)}</strong><p>${esc(r.id)} · ${esc(r.urgency)} · ${esc(origin.short)} EMS · ${r.radiusKm} km radius</p>${r.delivery?.adminHelp?.note?'<p>Last response: '+esc(r.delivery.adminHelp.note)+'</p>':''}<form data-help-route="${r.recordId}"><label class="field"><span>Hospital to contact</span><select name="hospitalId" data-testid="help-hospital-${r.id}" required><option value="">Choose a hospital</option>${candidates.map(h=>`<option value="${h.id}">${esc(h.name)} · ${Math.round(distance(origin,h))} km</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="confirmed" data-testid="help-confirm-${r.id}" required> I contacted this sample hospital and confirmed support for this resource.</label><button class="primary" data-testid="help-route-${r.id}">Send to hospital</button></form><details><summary>Add an update for EMS</summary><form data-help-note="${r.recordId}"><label class="field"><span>What should EMS know?</span><input name="reason" data-testid="help-note-${r.id}" maxlength="500" required></label><button class="secondary" data-testid="help-note-save-${r.id}">Save update</button></form></details></article>`;}).join('')||'<p class="muted">No resource-help requests waiting.</p>'}</div><small>In-app coordination only. No email, SMS or emergency dispatch is sent.</small></section>`;}

async function api(path,input){const r=await fetch(path,{method:input?'POST':'GET',headers:input?{'Content-Type':'application/json'}:{},body:input?JSON.stringify(input):undefined});const data=await r.json();if(r.status===401){location.assign('/login.html');throw Error('Sign in again.');}if(!r.ok)throw Error(data.error||'Could not save this change.');return data;}
async function load(){const me=await api('/api/auth/me');actor=me.actor;if(actor.role!=='admin'){location.assign('/');return;}const staff=await api('/api/staff'),policy=await api('/api/policy'),data=await api('/api/requests'),ready=await api('/api/readiness');
 $('#staff-app').innerHTML=`<header class="core-header"><a class="core-brand" href="/staff.html"><img class="brand-logo" data-testid="brand-logo" src="/logo.svg" alt="Hospital Connect logo"><span>Hospital Connect<small>Sample administrator</small></span></a><nav class="core-nav"><a href="/network.html">BC map</a><a href="/about.html">About Us</a><a href="/data-care.html">Data care</a><button id="sign-out" data-testid="sign-out">Sign out</button></nav></header><div class="core-banner">Shared example accounts only. Verification here is a prototype exercise using invented employee numbers, not proof of actual employment. Real patient data stays blocked.</div><div class="admin-intro"><div><p class="admin-eyebrow">ADMINISTRATION</p><h1>Administrator desk</h1><p>Help teams get connected and keep access up to date.</p></div><img src="/coordination-flow.svg" alt="EMS and hospital teams connected through Hospital Connect"></div><nav class="admin-shortcuts" aria-label="Administrator tasks"><a href="#resource-help">${symbol('help')}<span><strong>${data.requests.filter(r=>r.status==='Needs admin').length} ${data.requests.filter(r=>r.status==='Needs admin').length===1?'request needs':'requests need'} help</strong><small>Find a hospital for EMS</small></span></a><a href="#staff-access" data-open="staff-access">${symbol('hospital')}<span><strong>${staff.staff.filter(s=>s.status==='pending').length} staff awaiting approval</strong><small>Review access requests</small></span></a><a href="#admin-settings" data-open="admin-settings">${symbol('clock')}<span><strong>Settings & records</strong><small>Backup, storage and history</small></span></a></nav><p id="staff-error" class="core-error" role="alert"></p><p id="staff-status" class="core-alert" role="status"></p>${resourceHelpCards(data.requests,ready.facilities)}<details class="panel admin-section" id="staff-access"><summary><span>Staff access<small>Review new requests or update existing access</small></span></summary><p class="muted">Open a staff member to review their details. Approval requires an employee-number check.</p><div data-testid="staff-list">${[...staff.staff].sort((a,b)=>(a.status==='pending'?0:1)-(b.status==='pending'?0:1)).map(s=>`<article class="staff-card" data-testid="staff-${s.employeeNumber}"><div class="staff-heading"><strong>${esc(s.name)}</strong><span class="tag">${esc(s.status)}</span></div><p>${esc(s.email)} · ${esc(s.employeeNumber)}<br>${esc((s.role||s.requestedRole)==='ems'?'Dispatcher':(s.role||s.requestedRole)==='hospital'?'Hospital coordinator':s.role||s.requestedRole||'Role not assigned')}</p>${s.userId!==actor.userId?`<details data-expand="${s.userId}" class="staff-controls"><summary>Review access</summary><label class="field"><span>Role${fixedSample(s)?' · fixed sample desk':''}</span><select data-role="${s.userId}" ${fixedSample(s)?'disabled':''}><option value="hospital" ${assignedRole(s)==='hospital'?'selected':''}>Hospital coordinator</option><option value="ems" ${assignedRole(s)==='ems'?'selected':''}>Dispatcher</option></select></label><label class="field"><span>Hospital or EMS base</span><select data-facility="${s.userId}" ${fixedSample(s)?'disabled':''}>${hospitals.map(h=>`<option value="${h.id}" ${h.id===assignedFacility(s)?'selected':''}>${esc(h.name)}</option>`).join('')}</select></label><label class="field"><span>Reason for this decision</span><input data-reason="${s.userId}" placeholder="For example: sample employee number checked"></label><label class="check"><input type="checkbox" data-verified="${s.userId}"> I checked this invented number against the sample staff list.</label><div class="buttonrow"><button class="primary" data-staff-action="approved" data-user="${s.userId}">Approve</button><button class="secondary" data-staff-action="rejected" data-user="${s.userId}">Reject</button><button class="secondary" data-staff-action="suspended" data-user="${s.userId}">Suspend</button></div></details>`:'<small>You are signed in as this administrator</small>'}</article>`).join('')}</div></details><details class="panel admin-section" id="admin-settings"><summary><span>Backup settings<small>Set a follow-up target and backup contact</small></span></summary><form id="policy-form"><label class="field"><span>Follow up after (minutes)</span><input id="response-minutes" data-testid="response-minutes" type="number" min="1" max="1440" value="${policy.responseMinutes}" required></label><label class="field"><span>Backup contact</span><input id="backup-contact" data-testid="backup-contact" value="${esc(policy.backupContact)}" maxlength="200" required></label><p class="muted">Start the backup contact with DEMO. These targets do not set a clinically safe waiting time or promise 24/7 staffing.</p><button class="primary" data-testid="save-policy">Save settings</button></form></details><details class="panel admin-section" id="admin-storage"><summary><span>Stored requests<small>Storage rules and request deletion</small></span></summary><p>${esc(policy.retention)}</p><p>Deleting a request removes it from the active app store and leaves its reference, acting staff and reason in the audit history. Provider backup retention needs separate review before real-patient use.</p><div data-testid="deletion-list">${data.requests.map(r=>`<form class="delete-form staff-card" data-record="${r.recordId}"><strong>${esc(r.id)} · ${esc(r.resource)}</strong><label class="field"><span>Type ${esc(r.id)} to confirm</span><input name="reference" required></label><label class="field"><span>Deletion reason</span><input name="reason" required></label><button class="secondary">Delete example request</button></form>`).join('')||'<p>No example requests to delete.</p>'}</div></details><details class="panel admin-section" id="admin-history"><summary><span>Activity history<small>Who changed what, and when</small></span></summary><ol data-testid="admin-audit">${staff.audit.sort((a,b)=>b.at-a.at).map(e=>`<li>${esc(e.name)} · ${esc(e.action)} · ${esc(e.reference)} · ${esc(new Date(e.at).toLocaleString('en-CA',{timeZone:'America/Vancouver',dateStyle:'medium',timeStyle:'short'}))}${e.reason?' · '+esc(e.reason):''}</li>`).join('')||'<li>No administrative actions yet.</li>'}</ol></details>`;
 document.querySelectorAll('.admin-section, [data-expand]').forEach(d=>{const key=d.id||d.dataset.expand;d.open=expanded.has(key);d.ontoggle=()=>{if(d.open)expanded.add(key);else expanded.delete(key);};});
 document.querySelectorAll('[data-open]').forEach(a=>a.onclick=()=>{const d=document.getElementById(a.dataset.open);d.open=true;expanded.add(d.id);});
 document.querySelectorAll('[data-help-route]').forEach(f=>f.onsubmit=e=>{e.preventDefault();run(async()=>{const v=new FormData(f);await api('/api/requests/'+f.dataset.helpRoute+'/admin-route',{hospitalId:v.get('hospitalId'),resourceConfirmed:v.get('confirmed')==='on'});await load();$('#staff-status').textContent='Resource request routed to the confirmed hospital. EMS can track the response.';});});
 document.querySelectorAll('[data-help-note]').forEach(f=>f.onsubmit=e=>{e.preventDefault();run(async()=>{await api('/api/requests/'+f.dataset.helpNote+'/admin-note',{reason:new FormData(f).get('reason')});await load();$('#staff-status').textContent='Resource-help update saved for EMS.';});});
 $('#sign-out').onclick=async()=>{await api('/api/auth/logout',{});location.assign('/login.html');};
 document.querySelectorAll('[data-staff-action]').forEach(b=>b.onclick=()=>run(async()=>{const id=b.dataset.user;await api('/api/staff/'+id,{status:b.dataset.staffAction,role:$(`[data-role="${id}"]`).value,facilityId:$(`[data-facility="${id}"]`).value,employeeVerified:$(`[data-verified="${id}"]`).checked,reason:$(`[data-reason="${id}"]`).value});await load();$('#staff-status').textContent='Staff decision recorded.';}));
 $('#policy-form').onsubmit=e=>{e.preventDefault();run(async()=>{await api('/api/policy',{responseMinutes:Number($('#response-minutes').value),backupContact:$('#backup-contact').value});$('#staff-status').textContent='Backup policy saved.';});};
 document.querySelectorAll('.delete-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();const values=new FormData(f);run(async()=>{await api('/api/requests/'+f.dataset.record+'/delete',{reference:values.get('reference'),reason:values.get('reason')});await load();$('#staff-status').textContent='Example request deleted; audit metadata retained.';});});
}
let busy=false;async function run(fn){if(busy)return;busy=true;$('#staff-error').textContent='';$('#staff-status').textContent='Saving…';$('#staff-app').setAttribute('aria-busy','true');try{await fn();}catch(e){$('#staff-status').textContent='';$('#staff-error').textContent=e.message;$('#staff-error').scrollIntoView({block:'center'});}finally{busy=false;$('#staff-app').removeAttribute('aria-busy');}}
load().catch(e=>{$('#staff-app').innerHTML='<h1>Staff administration unavailable</h1><p role="alert">'+esc(e.message)+'</p><a href="/login.html">Return to sign-in</a>';});
